{
    if(!spi) {
        return 0;
    }
    uint16_t data;
    SPI_MUTEX_LOCK();
    while(spi->dev->cmd.usr);
    data = __spiTranslate16(spi->dev->data_buf[0] & 0xFFFF, !spi->dev->ctrl.rd_bit_order);
    SPI_MUTEX_UNLOCK();
    return data;
}

